1: package First_Match_Oracle with SPARK_Mode is
2:    function Find
3:      (Motif : String; Text : String; Case_Sensitive : Boolean) return Integer
4:    with
5:      Global => null,
6:      Pre => Motif'Length <= 6 and then Text'Length <= 10
7:        and then Motif'First = 1
8:        and then (Text'First = 1 or else Text'First = 5)
9:        and then (for all C of Motif => Character'Pos (C) <= 127)
10:        and then (for all C of Text => Character'Pos (C) <= 127),
11:      Post => Find'Result = -1 or else
12:        (Motif'Length > 0 and then Find'Result >= Text'First
13:         and then Find'Result <= Text'Last - Motif'Length + 1);
14: end First_Match_Oracle;

FILE fixture/first_match_oracle.adb
1: package body First_Match_Oracle with SPARK_Mode is
2:    function Fold (Value : Character; Sensitive : Boolean) return Character is
3:    begin
4:       if not Sensitive and then Value in 'A' .. 'Z' then
5:          return Character'Val
6:            (Character'Pos (Value) + Character'Pos ('a') - Character'Pos ('A'));
7:       end if;
8:       return Value;
9:    end Fold;
10: 
11:    function Matches
12:      (Motif : String; Text : String; Start : Positive;
13:       Sensitive : Boolean) return Boolean
14:    with
15:      Global => null,
16:      Pre => Motif'Length in 1 .. 6 and then Motif'First = 1
17:        and then Text'Length <= 10
18:        and then (Text'First = 1 or else Text'First = 5)
19:        and then Start >= Text'First
20:        and then Start <= Text'Last - Motif'Length + 1
21:    is
22:    begin
23:       --  At most six comparisons; Find admits only fitting starts.
24:       for Offset in 0 .. Motif'Length - 1 loop
25:          pragma Loop_Invariant
26:            (for all Prior in 0 .. Offset - 1 =>
27:               Fold (Motif (Motif'First + Prior), Sensitive) =
28:               Fold (Text (Start + Prior), Sensitive));
29:          if Fold (Motif (Motif'First + Offset), Sensitive) /=
30:            Fold (Text (Start + Offset), Sensitive)
31:          then
32:             return False;
33:          end if;
34:       end loop;
35:       return True;
36:    end Matches;
37: 
38:    function Find
39:      (Motif : String; Text : String; Case_Sensitive : Boolean) return Integer
40:    is
41:    begin
42:       --  Empty motif follows this pinned implementation's convention.
43:       if Motif'Length = 0 or else Motif'Length > Text'Length then
44:          return -1;
45:       end if;
46:       --  At most ten starts, in ascending absolute String-index order.
47:       for Start in Text'First .. Text'Last - Motif'Length + 1 loop
48:          pragma Loop_Invariant
49:            (for all Prior in Text'First .. Start - 1 =>
50:               not Matches (Motif, Text, Prior, Case_Sensitive));
51:          if Matches (Motif, Text, Start, Case_Sensitive) then
52:             return Start;
53:          end if;
54:       end loop;
55:       return -1;
56:    end Find;
57: end First_Match_Oracle;

