1: with Ada.Assertions;
2: with Ada.Text_IO;
3: 
4: package body Fixture_Results is
5:    Row_Count : Natural range 0 .. 25 := 0;
6:    Byte_Count : Natural range 0 .. 16_384 := 0;
7: 
8:    procedure Emit (Row : String) is
9:    begin
10:       Ada.Assertions.Assert
11:         (Row'Length in 1 .. 128 and then Row_Count < 25
12:          and then Byte_Count <= 16_384 - Row'Length - 1);
13:       Ada.Text_IO.Put_Line (Row);
14:       Row_Count := Row_Count + 1;
15:       Byte_Count := Byte_Count + Row'Length + 1;
16:    end Emit;
17: 
18:    function Decimal (Value : Integer) return String is
19:       Image : constant String := Integer'Image (Value);
20:    begin
21:       if Value < 0 then
22:          return Image;
23:       end if;
24:       return Image (Image'First + 1 .. Image'Last);
25:    end Decimal;
26: 
27:    procedure Search
28:      (Id : Case_Id; Expected : Integer; Oracle : Integer; Actual : Integer)
29:    is
30:    begin
31:       Emit ("SEARCH " & Case_Id'Image (Id) &
32:             " EXPECTED " & Decimal (Expected) &
33:             " ORACLE " & Decimal (Oracle) &
34:             " ACTUAL " & Decimal (Actual));
35:    end Search;
36: 
37:    procedure Free_Completed (Id : Case_Id) is
38:    begin
39:       --  Public normal return twice; no private-pointer or release claim.
40:       Emit ("FREE " & Case_Id'Image (Id) & " COMPLETED 2");
41:    end Free_Completed;
42: 
43:    procedure Consumer_D01 (First, Second, Third : Boolean) is
44:    begin
45:       Emit ("CONSUMER D01 " & Boolean'Image (First) & " " &
46:             Boolean'Image (Second) & " " & Boolean'Image (Third));
47:    end Consumer_D01;
48: 
49:    procedure Consumer_D02 (First, Second : Boolean) is
50:    begin
51:       Emit ("CONSUMER D02 " & Boolean'Image (First) & " " &
52:             Boolean'Image (Second));
53:    end Consumer_D02;
54: 
55:    procedure Complete is
56:    begin
57:       Ada.Assertions.Assert (Row_Count = 24);
58:       Emit ("COMPLETE SEARCH 11 FREE 11 CONSUMER 2");
59:       Ada.Assertions.Assert (Row_Count = 25);
60:       Ada.Text_IO.Flush;
61:    end Complete;
62: end Fixture_Results;

