1: """Finite public-result protocol; no allocator or native qualification claim."""
2: import sys
3: 
4: MAX_BYTES = 16_384
5: MAX_LINE = 128
6: EXPECTED_ROWS = (
7:     b"SEARCH C01 EXPECTED 3 ORACLE 3 ACTUAL 3", b"FREE C01 COMPLETED 2",
8:     b"SEARCH C02 EXPECTED -1 ORACLE -1 ACTUAL -1", b"FREE C02 COMPLETED 2",
9:     b"SEARCH C03 EXPECTED -1 ORACLE -1 ACTUAL -1", b"FREE C03 COMPLETED 2",
10:     b"SEARCH C04 EXPECTED 3 ORACLE 3 ACTUAL 3", b"FREE C04 COMPLETED 2",
11:     b"SEARCH C05 EXPECTED 1 ORACLE 1 ACTUAL 1", b"FREE C05 COMPLETED 2",
12:     b"SEARCH C06 EXPECTED -1 ORACLE -1 ACTUAL -1", b"FREE C06 COMPLETED 2",
13:     b"SEARCH C07 EXPECTED 7 ORACLE 7 ACTUAL 7", b"FREE C07 COMPLETED 2",
14:     b"SEARCH C08 EXPECTED -1 ORACLE -1 ACTUAL -1", b"FREE C08 COMPLETED 2",
15:     b"SEARCH C09 EXPECTED -1 ORACLE -1 ACTUAL -1", b"FREE C09 COMPLETED 2",
16:     b"SEARCH C10 EXPECTED 1 ORACLE 1 ACTUAL 1", b"FREE C10 COMPLETED 2",
17:     b"SEARCH C10R EXPECTED 3 ORACLE 3 ACTUAL 3", b"FREE C10R COMPLETED 2",
18:     b"CONSUMER D01 TRUE TRUE FALSE", b"CONSUMER D02 TRUE FALSE",
19:     b"COMPLETE SEARCH 11 FREE 11 CONSUMER 2",
20: )
21: 
22: 
23: class InvalidResults(ValueError):
24:     """Rejected, bounded protocol input."""
25: 
26: 
27: def validate(data: bytes) -> None:
28:     """Accept exactly 25 ordered canonical ASCII rows with final LF."""
29:     if not isinstance(data, bytes):
30:         raise InvalidResults("INPUT_TYPE")
31:     if len(data) > MAX_BYTES:
32:         raise InvalidResults("EXCESS_BYTES")
33:     if not data.endswith(b"\n"):
34:         raise InvalidResults("MISSING_FINAL_LF")
35:     rows = data.split(b"\n", 26)
36:     if len(rows) != 26 or rows[-1] != b"":
37:         raise InvalidResults("ROW_COUNT")
38:     for index in range(25):
39:         row = rows[index]
40:         if not 1 <= len(row) <= MAX_LINE:
41:             raise InvalidResults("LINE_LENGTH")
42:         if row != EXPECTED_ROWS[index]:
43:             raise InvalidResults("ROW_MISMATCH")
44: 
45: 
46: def emit(stream, message: str) -> None:
47:     if len(message) > 128:
48:         raise OSError("OUTPUT_LIMIT")
49:     if stream.write(message) != len(message):
50:         raise OSError("INCOMPLETE_OUTPUT")
51:     stream.flush()
52: 
53: 
54: def main() -> int:
55:     """One bounded read; external admitted harness supplies I/O deadline."""
56:     try:
57:         data = sys.stdin.buffer.read(MAX_BYTES + 1)
58:         validate(data)
59:     except (InvalidResults, OSError):
60:         # Do not echo attacker-controlled input or unbounded exception text.
61:         emit(sys.stderr, "INVALID RESULTS\n")
62:         return 2
63:     emit(sys.stdout, "VALID PUBLIC RESULTS\n")
64:     return 0
65: 
66: 
67: if __name__ == "__main__":
68:     raise SystemExit(main())

